<?php
declare(strict_types=1);
if (!isset($row, $base, $files, $deletedFiles, $escape)) return;
$active = $files[$row['id']] ?? [];
$removed = $deletedFiles[$row['id']] ?? [];
$renderFileAction = static function (array $file, string $action) use ($row, $base, $year, $item, $escape): void {
?>
<form method="post" action="<?= $escape($base) ?>" class="attachment-action" data-action="<?= $action ?>"><input type="hidden" name="csrf" value="<?= $escape($_SESSION['leadership_csrf']) ?>"><input type="hidden" name="year" value="<?= $year ?>"><input type="hidden" name="item" value="<?= $item ?>"><input type="hidden" name="id" value="<?= $row['id'] ?>"><input type="hidden" name="revision" value="<?= $row['revision'] ?>"><input type="hidden" name="file_id" value="<?= $file['id'] ?>"><input type="hidden" name="file_action" value="<?= $action ?>"><button type="submit" class="<?= $action === 'delete_file' ? 'delete-attachment' : '' ?>" aria-label="<?= $escape($file['original_name'] . ($action === 'delete_file' ? ' 삭제' : ' 복원')) ?>"><?= $action === 'delete_file' ? '삭제' : '복원' ?></button></form>
<?php }; ?>
<?php if ($item === '1.1.3'): $signedCount = count(array_filter($active, static fn(array $file): bool => ($file['file_kind'] ?? '') === 'signed_scan')); ?>
<section class="signed-scan-panel"><h4>서명본 증빙 <span><?= $signedCount ? '첨부 ' . $signedCount . '개' : '미첨부' ?></span></h4><p class="hint">안전순찰일지 출력 → 순찰자 서명 → 스캔 후 이 기록에 첨부해 주세요. PDF·JPG·PNG, 파일별 10MB / 합계 30MB, 최대 5개.</p>
<form method="post" action="<?= $escape($base) ?>" enctype="multipart/form-data" class="signed-scan-upload"><input type="hidden" name="csrf" value="<?= $escape($_SESSION['leadership_csrf']) ?>"><input type="hidden" name="year" value="<?= $year ?>"><input type="hidden" name="item" value="<?= $item ?>"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><input type="hidden" name="revision" value="<?= (int)$row['revision'] ?>"><input type="hidden" name="form_action" value="upload_signed_scan"><label>서명본 스캔 파일<input type="file" name="signed_scan[]" accept=".pdf,.jpg,.jpeg,.png" multiple required></label><button class="primary">서명본 업로드</button></form></section>
<?php endif; ?>
<div class="file-links"><?php foreach ($active as $file): ?><div class="file-item"><a href="<?= $escape($base) ?>&amp;file=<?= $file['id'] ?>"><?= ($file['file_kind'] ?? '') === 'signed_scan' ? '서명본' : '첨부' ?> · <?= $escape($file['original_name']) ?></a><?php if ($item === '1.1.4' && $file['mime'] === 'application/pdf'): ?><a class="button" href="<?= $escape($base) ?>&amp;file=<?= (int)$file['id'] ?>&amp;inline=1" target="_blank" rel="noopener" data-pdf-preview data-pdf-name="<?= $escape($file['original_name']) ?>" data-pdf-download="<?= $escape($base) ?>&amp;file=<?= (int)$file['id'] ?>" aria-haspopup="dialog" aria-controls="meeting-pdf-viewer">PDF 보기</a><?php endif; ?><?php $renderFileAction($file, 'delete_file'); ?></div><?php endforeach; ?><?php if (!$active): ?><span class="muted">첨부 증빙 없음</span><?php endif; ?></div>
<?php if ($removed): ?><details class="deleted-files"><summary>삭제된 첨부파일 <?= count($removed) ?>개</summary><p class="hint">삭제된 파일은 다운로드할 수 없습니다. 복원하면 첨부 목록에 다시 표시됩니다.</p><?php foreach ($removed as $file): ?><div class="file-item"><span><?= $escape($file['original_name']) ?> <small class="muted">· <?= $escape($file['deleted_at']) ?> 삭제</small></span><?php $renderFileAction($file, 'restore_file'); ?></div><?php endforeach; ?></details><?php endif; ?>
